import React from 'react';
import { Link } from 'react-router-dom';

function TwoColumnSection({ 
  title, 
  description, 
  buttonText, 
  buttonLink, 
  image, 
  badgeText, 
  badgeSubtext 
}) {
  return (
    <div className="bg-white py-16 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto">
        <div className="flex flex-col md:flex-row gap-8 md:gap-16">
          {/* Bloc de gauche avec titre et description */}
          <div className="w-full md:w-1/2 flex flex-col justify-center">
            <h2 className="text-3xl md:text-4xl lg:text-5xl font-bold text-gray-900 leading-tight">
              {title}
            </h2>
            <p className="mt-6 text-gray-600 text-lg md:text-xl max-w-lg">
              {description}
            </p>
            {buttonText && (
              <div className="mt-8">
                <Link
                  to={buttonLink || "#"}
                  className="inline-block px-6 py-3 bg-blue-700 text-white font-medium rounded-md hover:bg-blue-800 transition duration-300"
                >
                  {buttonText}
                </Link>
              </div>
            )}
          </div>
          
          {/* Bloc de droite avec image et badge */}
          <div className="w-full md:w-1/2 relative mt-8 md:mt-0">
            <div className="overflow-hidden rounded-t-2xl h-[400px] flex items-center justify-center">
              <img 
                src={image} 
                alt="Section image" 
                className="w-full object-contain" 
              />
            </div>
            
            {/* Badge d'expérience */}
            {badgeText && (
              <div className="absolute -bottom-5 -right-5 w-28 h-28 bg-red-600 rounded-full flex items-center justify-center text-center p-2 shadow-lg">
                <div className="text-white font-bold">
                  <span className="block text-xl">{badgeText}</span>
                  <span className="block text-sm">{badgeSubtext}</span>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default TwoColumnSection;
